/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['anndata','python-annoy','scipy']:
    print('repo', repo)
    found=[]
    for page in range(1, 80):
        url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=100&page={page}'
        try:
            with urllib.request.urlopen(url, timeout=30) as r:
                data=json.load(r)
        except Exception as e:
            print('ERR', e)
            break
        for t in data.get('tags', []):
            name=t.get('name','')
            if repo=='anndata' and any(v in name for v in ['0.12','0.11','0.10','0.9']):
                found.append(name)
            if repo=='scipy' and any(v in name for v in ['1.14','1.13','1.12']):
                found.append(name)
        if not data.get('has_additional'):
            break
    print('\\n'.join(found[:50]))
    print('count', len(found))
PY"

